command:
cd /app && python3 - <<'PY'
from pathlib import Path
p = Path('crates/wasmi/src/engine/coredump.rs')
s = p.read_text()
# Add use core::fmt
s = s.replace('''use alloc::{string::String, vec, vec::Vec};''', '''use alloc::{string::String, vec, vec::Vec};
use core::fmt;''')
# Add Debug for CoredumpMemory (replace derive(Debug, Clone))
s = s.replace('''/// A linear memory captured for coredump generation.
#[derive(Debug, Clone)]
pub(crate) struct CoredumpMemory {''', '''/// A linear memory captured for coredump generation.
#[derive(Clone)]
pub(crate) struct CoredumpMemory {''')
# Add Debug impl after CoredumpMemory struct
s = s.replace('''/// A global variable captured for coredump generation.
#[derive(Debug, Clone)]''', '''impl fmt::Debug for CoredumpMemory {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        f.debug_struct("CoredumpMemory")
            .field("key", &self.key)
            .field("ty", &self.ty)
            .field("data_len", &self.data.len())
            .finish()
    }
}

/// A global variable captured for coredump generation.
#[derive(Debug, Clone)]''')
# Add Debug for Coredump: replace derive(Debug, Default) with derive(Default) and add impl
s = s.replace('''/// A Wasm coredump.
///
/// # Note
///
/// This is the structured representation used while constructing a coredump.
/// The final serialized bytes are stored in [`Coredump::bytes`].
#[derive(Debug, Default)]
pub(crate) struct Coredump {''', '''/// A Wasm coredump.
///
/// # Note
///
/// This is the structured representation used while constructing a coredump.
/// The final serialized bytes are stored in [`Coredump::bytes`].
#[derive(Default)]
pub(crate) struct Coredump {''')
# Add Debug impl for Coredump before "impl Coredump {"
s = s.replace('''impl Coredump {
    /// Creates a new empty [`Coredump`] with the given `executable_name`.''', '''impl fmt::Debug for Coredump {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        f.debug_struct("Coredump")
            .field("executable_name", &self.executable_name)
            .field("modules", &self.modules)
            .field("instances", &self.instances)
            .field("frames", &self.frames)
            .field("memories", &self.memories)
            .field("globals", &self.globals)
            .field("bytes_len", &self.bytes.len())
            .finish()
    }
}

impl Coredump {
    /// Creates a new empty [`Coredump`] with the given `executable_name`.''')
p.write_text(s)
print("done")
PY
